// M06-J03 section 1: recovery on a real-sized book (3 acts, 60 chapters, 320 scenes, ~130 000 words, 220 entries, 40 threads, 120 events, 30 notes,
// 10 exceptions, suggestions and receipts), generated by packages/format/test/build-large.mjs into a temp folder.
// Long: run with `npm run test:large` (one file at a time, so the timings are not skewed by other work). Every wait polls with a deadline.
import { test, after } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import fs from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createFsRepository } from '../../../packages/core/src/index.mjs';
import { validate } from '../../../packages/format/src/index.mjs';
import { REPO_ROOT } from './helpers.mjs';
import { killAll, runCli } from './proc-helpers.mjs';
import { collectAnswers, copyLarge, firstDifference, getJson, largeBook, makeHome, mapLimit, readTree, reportTime, sameBytes, startLarge, stopAll, waitFor, waitIndexFresh } from './large-helpers.mjs';

after(async () => {
  await killAll();
  await stopAll();
});

const here = path.dirname(fileURLToPath(import.meta.url));
const CHILD = path.join(here, 'fixtures', 'large-fault-child.mjs');
const { bookId, scenes, stats } = largeBook();
// what an operation writes after its own atomic step, in separate files that are not part of "the book": the receipts (provenance/) and the day's writing log (activity/)
const SIDE_EFFECTS = ['provenance', 'activity'];
/** The book's files for comparing states: a suggestion file carries the time it was decided, which differs between two runs of the same accept, so that one value is blanked. */
async function bookState(root) {
  const files = await readTree(root, { skip: SIDE_EFFECTS });
  for (const [rel, bytes] of files) {
    if (rel.startsWith('suggestions/')) files.set(rel, Buffer.from(bytes.toString('utf8').replace(/\d{4}-\d\d-\d\dT\d\d:\d\d:\d\dZ/g, 'TIME')));
  }
  return files;
}
const BASE_BUDGET = { rebuild: 30000, reconcile: 10000 };

test('the generated book has the contract shape and validates clean', async () => {
  assert.equal(stats.acts, 3);
  assert.equal(stats.chapters, 60);
  assert.equal(stats.scenes, 320);
  assert.equal(stats.entries, 220);
  assert.equal(stats.threads, 40);
  assert.equal(stats.events, 120);
  assert.ok(stats.words >= 120000 && stats.words <= 140000, `words ${stats.words}`);
  const v = await validate(largeBook().root);
  assert.deepEqual(v.diagnostics, [], 'no diagnostics at all');
  console.log(`# LARGE-BOOK ${JSON.stringify(stats)}`);
});

test('1. delete .storyforge/ and restart: the index is rebuilt and every API answer is the same', async () => {
  const root = await copyLarge();
  const home = await makeHome();
  let { app, startedAt } = await startLarge(root, home);
  await waitIndexFresh(app, startedAt);
  const before = await collectAnswers(app, bookId);
  assert.equal(before.sceneCount, 320);
  assert.equal(before.answers.entries.length ?? before.answers.entries.entries.length, 220);
  assert.equal(before.answers['receipts/verify'].ok, true);
  await app.stop();

  await fs.rm(path.join(root, '.storyforge'), { recursive: true, force: true });
  ({ app, startedAt } = await startLarge(root, home));
  const rebuildMs = await waitIndexFresh(app, startedAt);
  reportTime('1 rebuild after deleting .storyforge (start -> every index fresh)', rebuildMs, BASE_BUDGET.rebuild);
  assert.ok(rebuildMs <= BASE_BUDGET.rebuild, `rebuild took ${rebuildMs} ms`);
  const after = await collectAnswers(app, bookId);
  assert.equal(firstDifference(before.answers, after.answers), null);
  await app.stop();
});

test('2. backup, restore into an empty folder: byte-identical, validates, opens with no index, rebuild equals the original answers', async () => {
  const root = await copyLarge();
  const home = await makeHome();
  const { app, startedAt } = await startLarge(root, home);
  await waitIndexFresh(app, startedAt);
  const original = await collectAnswers(app, bookId);
  await app.stop();

  const out = await fs.mkdtemp(path.join((await import('node:os')).tmpdir(), 'sf-large-bk-'));
  const zip = path.join(out, 'backup.zip');
  let t = Date.now();
  const b = await runCli(['backup', '--library', root, '--book', 'large-book', '--out', zip, '--provenance']);
  assert.equal(b.code, 0, b.output);
  reportTime('2 backup', Date.now() - t);
  const target = path.join(out, 'restored');
  t = Date.now();
  const r = await runCli(['restore', '--from', zip, '--to', target]);
  assert.equal(r.code, 0, r.output);
  reportTime('2 restore', Date.now() - t);

  const a = await readTree(root);
  const c = await readTree(target);
  assert.deepEqual([...c.keys()].sort(), [...a.keys()].sort(), 'same files');
  for (const [rel, bytes] of a) assert.ok(sameBytes(bytes, c.get(rel)), `${rel} differs after restore`);
  assert.deepEqual((await validate(target)).diagnostics, []);
  await assert.rejects(fs.stat(path.join(target, '.storyforge')), 'the restored folder has no index');

  const started = await startLarge(target, home);
  const restored = started.app;
  const ms = await waitIndexFresh(restored, started.startedAt);
  reportTime('2 open restored folder with no index (start -> fresh)', ms, BASE_BUDGET.rebuild);
  const again = await collectAnswers(restored, bookId);
  // a restored file is a new file: its modified time (`updated_at`) is the only thing allowed to differ
  assert.equal(firstDifference(original.answers, again.answers, { ignore: ['updated_at'] }), null);
  await restored.stop();
});

// ---- 3. interrupted writes ----------------------------------------------------------------------------------------------------------------------

const FAULT_POINTS = ['after-journal', 'after-trash', 'after-tmp', 'after-rename', 'before-done'];

function runChild(root, at, op, args) {
  return spawnSync(process.execPath, [CHILD, JSON.stringify({ root, at, op, bookId, args })], { cwd: REPO_ROOT, encoding: 'utf8', timeout: 120000 });
}

const OPS = {
  'body save': () => ({ op: 'body', args: { sceneId: scenes[40].id, body: 'The tide went out before dawn, and the whole book changed with it.\n\nNobody spoke on the ferry.\n' } }),
  'scene move': () => ({ op: 'move', args: { sceneId: scenes[100].id, chapter: scenes[10].chapter, after: scenes[10].id } }),
  'chapter renumber (every chapter folder renamed)': () => ({ op: 'renumber', args: { step: 10 } }),
  'suggestion accept': () => ({ op: 'accept', args: { suggestionId: null } }),
};

for (const [name, make] of Object.entries(OPS)) {
  test(`3. ${name}: interrupted at every store fault point, recovery leaves the book fully before or fully after`, async () => {
    const root0 = await copyLarge();
    const spec = make();
    if (spec.op === 'accept') {
      const repo = createFsRepository(root0, { watch: false, pollMs: 0 });
      spec.args.suggestionId = (await repo.listSuggestions(bookId, {})).suggestions[0].id;
      await repo.close();
    }
    const before = await bookState(root0);
    // the "all new" state: the same operation on another copy, run to the end
    const refRoot = await copyLarge();
    const ref = runChild(refRoot, null, spec.op, spec.args);
    assert.equal(ref.status, 0, `${ref.stdout}${ref.stderr}`);
    const afterState = await bookState(refRoot);
    let changed = 0;
    for (const [rel, bytes] of afterState) if (!before.has(rel) || !sameBytes(bytes, before.get(rel))) changed++;
    assert.ok(changed >= 1, 'the operation changes something');

    const seen = new Set();
    for (const at of FAULT_POINTS) {
      const root = await copyLarge();
      const child = runChild(root, at, spec.op, spec.args);
      assert.equal(child.status, 86, `child exit at ${at}: ${child.stdout}${child.stderr}`);
      // restart: opening the repository settles the journal
      const repo = createFsRepository(root, { watch: false, pollMs: 0 });
      const report = await repo.recover();
      assert.deepEqual(report.needsAttention, [], `${at}: nothing needs attention`);
      await repo.close();
      const now = await bookState(root);
      const differs = (ref) => [...new Set([...ref.keys(), ...now.keys()])].filter((rel) => !ref.has(rel) || !now.has(rel) || !sameBytes(ref.get(rel), now.get(rel)));
      const state = differs(before).length === 0 ? 'before' : differs(afterState).length === 0 ? 'after' : 'mixed';
      assert.notEqual(state, 'mixed', `${at}: the book must be byte-identical to all-before or all-after, never mixed (differs from before: ${differs(before).slice(0, 4)}; from after: ${differs(afterState).slice(0, 4)})`);
      seen.add(state);
      assert.deepEqual((await validate(root)).diagnostics.filter((d) => d.severity !== 'info'), [], `${at}: validate() is clean`);
      // nothing half-written is left behind
      const stray = [...now.keys()].filter((k) => /\.(tmp|partial)$/i.test(k) || /(^|\/)\.[^/]*\.tmp/.test(k));
      assert.deepEqual(stray, [], `${at}: no stray temp files`);
    }
    console.log(`# LARGE-FAULTS ${name}: outcomes ${[...seen].join('+')}`);
  });
}

// ---- 4. external edits -----------------------------------------------------------------------------------------------------------------------------

test('4. 50 scene files rewritten outside the app within 2 s are reconciled within 10 s, and the index equals a full rebuild', async () => {
  const root = await copyLarge();
  const home = await makeHome();
  const { app, startedAt } = await startLarge(root, home);
  await waitIndexFresh(app, startedAt);
  const picked = scenes.filter((_, i) => i % 6 === 0).slice(0, 50);
  assert.equal(picked.length, 50);
  const wordsBefore = new Map((await getJson(app, `/api/books/${bookId}`)).acts.flatMap((a) => a.chapters.flatMap((c) => c.scenes)).map((s) => [s.id, s.word_count]));
  const t0 = Date.now();
  const marker = 'Edited outside the app';
  await mapLimit(picked, 10, async (s, i) => {
    const file = path.join(root, ...s.rel.split('/'));
    const text = await fs.readFile(file, 'utf8');
    await fs.writeFile(file, `${text}${marker} ${i}.\n`);
  });
  const writeMs = Date.now() - t0;
  assert.ok(writeMs <= 2000, `the 50 writes took ${writeMs} ms (must be within 2 s)`);

  const words = async () => new Map((await getJson(app, `/api/books/${bookId}`)).acts.flatMap((a) => a.chapters.flatMap((c) => c.scenes)).map((s) => [s.id, s.word_count]));
  await waitFor(
    async () => {
      const now = await words();
      return picked.every((s) => now.get(s.id) === wordsBefore.get(s.id) + 5);
    },
    { timeout: 30000, interval: 100, what: '50 scenes reconciled (five more words each)' },
  );
  await waitIndexFresh(app, t0, 10000);
  const reconcileMs = Date.now() - t0;
  reportTime('4 external edits: first write -> every scene and the index reconciled', reconcileMs, 12000);
  const live = await collectAnswers(app, bookId);
  for (const [i, s] of [...picked.entries()].filter(([k]) => k % 10 === 0)) {
    const body = (await getJson(app, `/api/books/${bookId}/scenes/${s.id}`)).body;
    assert.ok(body.includes(`${marker} ${i}.`), `scene ${i} shows the outside edit`);
  }
  const rb = await app.post('/api/index/rebuild', {});
  assert.equal(rb.status, 200, rb.text);
  await waitIndexFresh(app);
  const rebuilt = await collectAnswers(app, bookId);
  assert.equal(firstDifference(live.answers, rebuilt.answers), null, 'the reconciled index answers like a full rebuild');
  await app.stop();
});

// ---- 5. invalid files ------------------------------------------------------------------------------------------------------------------------------

test('5. five corrupt files: the app stays up and lists exactly those problems; every other scene opens and saves; fixing them clears the list', async () => {
  const root = await copyLarge();
  const home = await makeHome();
  const rel = (i) => scenes[i].rel;
  const originals = new Map();
  const corrupt = [
    // bad YAML
    [rel(3), (t) => t.replace('status: ', 'status: [unclosed\nstatus2: ')],
    // duplicate id (a copy of another scene's id)
    [rel(60), (t) => t.replace(/^id: .*$/m, `id: ${scenes[61].id}`)],
    // broken link in the prose
    [rel(120), (t) => `${t}See [[no-such-entry-anywhere]].\n`],
    // a byte order mark
    [rel(180), (t) => String.fromCharCode(0xfeff) + t],
    // truncated in the middle of the front matter
    [rel(240), (t) => t.slice(0, t.indexOf('characters:') + 6)],
  ];
  for (const [file, fn] of corrupt) {
    const abs = path.join(root, ...file.split('/'));
    const text = await fs.readFile(abs, 'utf8');
    originals.set(file, text);
    await fs.writeFile(abs, fn(text));
  }
  const bad = new Set(corrupt.map(([f]) => f));
  const { app, startedAt } = await startLarge(root, home);
  await waitFor(async () => (await app.get('/api/health')).status === 200, { what: 'health' });
  await waitIndexFresh(app, startedAt).catch(() => {});
  const problems = async () => {
    const d = await getJson(app, `/api/books/${bookId}/diagnostics`);
    const list = Array.isArray(d) ? d : d.diagnostics ?? [];
    return list.filter((x) => x.severity !== 'info');
  };
  const listed = await problems();
  // what the five corruptions are expected to cause: their own problems, and (E301) the references that pointed at an id the corruption made unreadable
  const lost = [scenes[3].id, scenes[60].id, scenes[240].id];
  const dependent = (p) => p.code === 'E301' && lost.some((id) => p.message.endsWith(id));
  const key = (p) => `${p.code} | ${p.file}`;
  assert.deepEqual(
    listed.filter((p) => !dependent(p)).map(key).sort(),
    [`E100 | ${rel(3)}`, `E201 | ${rel(60)}`, `E201 | ${rel(61)}`, `E301 | ${rel(120)}`, `W204 | ${rel(180)}`, `E100 | ${rel(240)}`].sort(),
    'exactly the five corrupt files are reported (the duplicate id on both of the two files that share it)',
  );
  const files = new Set(listed.map((p) => p.file));
  for (const f of bad) assert.ok(files.has(f), `${f} is reported`);
  console.log(`# LARGE-INVALID reported: ${listed.map((p) => `${p.code} ${p.file.split('/').pop()}`).join('; ')}`);

  // the app stays up and every other scene opens and saves
  const others = scenes.filter((s) => !bad.has(s.rel) && s.rel !== rel(61)).filter((_, i) => i % 15 === 0);
  assert.ok(others.length >= 20);
  for (const s of others) {
    const got = await app.get(`/api/books/${bookId}/scenes/${s.id}`);
    assert.equal(got.status, 200, `${s.id} opens`);
    const put = await app.put(`/api/books/${bookId}/scenes/${s.id}/body`, { body: `${got.json.body}Saved while the book had problems.\n`, base_sha256: got.json.sha256 });
    assert.equal(put.status, 200, `${s.id} saves: ${put.text}`);
    const onDisk = await fs.readFile(path.join(root, ...s.rel.split('/')), 'utf8');
    assert.ok(onDisk.endsWith('Saved while the book had problems.\n'));
  }
  assert.equal((await app.get('/api/health')).status, 200);

  // fix the files: the problems clear
  for (const [file, text] of originals) await fs.writeFile(path.join(root, ...file.split('/')), text);
  await waitFor(async () => (await problems()).length === 0, { timeout: 30000, interval: 200, what: 'problems cleared after the fix' });
  assert.deepEqual((await validate(root)).diagnostics, []);
  await app.stop();
});
